use clap::{Arg, ArgAction, Command, ValueHint};
use clap::builder::{PossibleValue, PossibleValuesParser, ValueParser};
use std::ffi::{OsString, OsStr};
use std::num::NonZeroUsize;
use std::str::FromStr;

#[derive(Debug, Clone)]
enum MaxDepth {
    Inf,
    Finite(NonZeroUsize),
}

impl FromStr for MaxDepth {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let t = s.trim();
        if t == "inf" {
            return Ok(MaxDepth::Inf);
        }
        match t.parse::<NonZeroUsize>() {
            Ok(v) => Ok(MaxDepth::Finite(v)),
            Err(e) => Err(format!("Value is neither \"inf\" nor a positive integer: {}", e)),
        }
    }
}

#[derive(Debug, Clone)]
enum Threads {
    Auto,
    Max,
    Num(NonZeroUsize),
}

impl FromStr for Threads {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let t = s.trim();
        if t == "auto" {
            return Ok(Threads::Auto);
        }
        if t == "max" {
            return Ok(Threads::Max);
        }
        match t.parse::<NonZeroUsize>() {
            Ok(v) => Ok(Threads::Num(v)),
            Err(e) => Err(format!("Value is neither \"auto\", \"max\", nor a number: {}", e)),
        }
    }
}

#[derive(Debug, Clone)]
struct MinRatio(f64);

impl FromStr for MinRatio {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let v: f64 = s.parse::<f64>().map_err(|e: std::num::ParseFloatError| e.to_string())?;
        if v.is_nan() {
            return Ok(MinRatio(v));
        }
        if v < 0.0 {
            return Err("less than 0".to_string());
        }
        if v >= 1.0 {
            return Err("greater than or equal to 1".to_string());
        }
        Ok(MinRatio(v))
    }
}

fn build_cli() -> Command {
    Command::new("pdu")
        .version("0.21.1")
        .about("Summarize disk usage of the set of files, recursively for directories.")
        .long_about("Summarize disk usage of the set of files, recursively for directories.\n\nCopyright: Apache-2.0 © 2021 Hoàng Văn Khải <https://github.com/KSXGitHub/>\nSponsor: https://github.com/sponsors/KSXGitHub")
        .after_help("$ pdu\n    $ pdu path/to/file/or/directory\n    $ pdu file.txt dir/\n    $ pdu --quantity=apparent-size\n    $ pdu --deduplicate-hardlinks\n    $ pdu --bytes-format=plain\n    $ pdu --bytes-format=binary\n    $ pdu --min-ratio=0\n    $ pdu --min-ratio=0.05\n    $ pdu --min-ratio=0 --max-depth=inf --json-output | jq\n    $ pdu --json-input < disk-usage.json")
        .after_long_help("Examples:\n    Show disk usage chart of current working directory\n    $ pdu\n\n    Show disk usage chart of a single file or directory\n    $ pdu path/to/file/or/directory\n\n    Compare disk usages of multiple files and/or directories\n    $ pdu file.txt dir/\n\n    Show chart in apparent sizes instead of block sizes\n    $ pdu --quantity=apparent-size\n\n    Detect and subtract the sizes of hardlinks from their parent nodes\n    $ pdu --deduplicate-hardlinks\n\n    Show sizes in plain numbers instead of metric units\n    $ pdu --bytes-format=plain\n\n    Show sizes in base 2¹⁰ units (binary) instead of base 10³ units (metric)\n    $ pdu --bytes-format=binary\n\n    Show disk usage chart of all entries regardless of size\n    $ pdu --min-ratio=0\n\n    Only show disk usage chart of entries whose size is at least 5% of total\n    $ pdu --min-ratio=0.05\n\n    Show disk usage data as JSON instead of chart\n    $ pdu --min-ratio=0 --max-depth=inf --json-output | jq\n\n    Visualize existing JSON representation of disk usage data\n    $ pdu --json-input < disk-usage.json")
        .arg(Arg::new("json-input").long("json-input").help("Read JSON data from stdin").action(ArgAction::SetTrue).conflicts_with_all(["quantity", "deduplicate-hardlinks"]))
        .arg(Arg::new("json-output").long("json-output").help("Print JSON data instead of an ASCII chart").action(ArgAction::SetTrue))
        .arg(Arg::new("bytes-format").short('b').long("bytes-format").value_name("BYTES_FORMAT").help("How to display the numbers of bytes").value_parser(PossibleValuesParser::new([
            PossibleValue::new("plain").help("Display plain number of bytes without units"),
            PossibleValue::new("metric").help("Use metric scale, i.e. 1K = 1000B, 1M = 1000K, and so on"),
            PossibleValue::new("binary").help("Use binary scale, i.e. 1K = 1024B, 1M = 1024K, and so on"),
        ])).default_value("metric"))
        .arg(Arg::new("deduplicate-hardlinks").short('H').long("deduplicate-hardlinks").visible_aliases(["detect-links", "dedupe-links"]).help("Detect and subtract the sizes of hardlinks from their parent directory totals").action(ArgAction::SetTrue).conflicts_with("json-input"))
        .arg(Arg::new("top-down").long("top-down").help("Print the tree top-down instead of bottom-up").action(ArgAction::SetTrue))
        .arg(Arg::new("align-right").long("align-right").help("Set the root of the bars to the right").action(ArgAction::SetTrue))
        .arg(Arg::new("quantity").short('q').long("quantity").value_name("QUANTITY").help("Aspect of the files/directories to be measured").value_parser(PossibleValuesParser::new([
            PossibleValue::new("apparent-size").help("Measure apparent sizes"),
            PossibleValue::new("block-size").help("Measure block sizes (block-count * 512B)"),
            PossibleValue::new("block-count").help("Count numbers of blocks"),
        ])).default_value("block-size").conflicts_with("json-input"))
        .arg(Arg::new("max-depth").short('d').long("max-depth").visible_alias("depth").value_name("MAX_DEPTH").help("Maximum depth to display the data. Could be either \"inf\" or a positive integer").value_parser(clap::value_parser!(MaxDepth)).default_value("10"))
        .arg(Arg::new("total-width").short('w').long("total-width").visible_alias("width").value_name("TOTAL_WIDTH").help("Width of the visualization").value_parser(clap::value_parser!(usize)).conflicts_with("column-width"))
        .arg(Arg::new("column-width").long("column-width").value_names(["TREE_WIDTH", "BAR_WIDTH"]).help("Maximum widths of the tree column and width of the bar column").value_parser(clap::value_parser!(usize)).num_args(2).action(ArgAction::Append).conflicts_with("total-width"))
        .arg(Arg::new("min-ratio").short('m').long("min-ratio").value_name("MIN_RATIO").help("Minimal size proportion required to appear").value_parser(clap::value_parser!(MinRatio)).default_value("0.01"))
        .arg(Arg::new("no-sort").long("no-sort").help("Do not sort the branches in the tree").action(ArgAction::SetTrue))
        .arg(Arg::new("silent-errors").short('s').long("silent-errors").visible_alias("no-errors").help("Prevent filesystem error messages from appearing in stderr").action(ArgAction::SetTrue))
        .arg(Arg::new("progress").short('p').long("progress").help("Report progress being made at the expense of performance").action(ArgAction::SetTrue))
        .arg(Arg::new("threads").long("threads").value_name("THREADS").help("Set the maximum number of threads to spawn. Could be either \"auto\", \"max\", or a positive integer").value_parser(clap::value_parser!(Threads)).default_value("auto"))
        .arg(Arg::new("omit-json-shared-details").long("omit-json-shared-details").help("Do not output `.shared.details` in the JSON output").action(ArgAction::SetTrue).requires_all(["json-output", "deduplicate-hardlinks"]))
        .arg(Arg::new("omit-json-shared-summary").long("omit-json-shared-summary").help("Do not output `.shared.summary` in the JSON output").action(ArgAction::SetTrue).requires_all(["json-output", "deduplicate-hardlinks"]))
        .arg(Arg::new("files").value_name("FILES").help("List of files and/or directories").num_args(0..).value_hint(ValueHint::AnyPath))
}

fn main() {
    let m = build_cli().get_matches();
    println!("parsed ok: {:?}", m.get_flag("json-input"));
}
