use clap::{Arg, ArgAction, Command, ValueHint};
use clap::builder::{PossibleValue, PossibleValuesParser};
use std::ffi::{OsString, OsStr};
use std::num::NonZeroUsize;
use std::str::FromStr;
use std::os::unix::ffi::OsStrExt;

#[derive(Debug, Clone)]
enum MaxDepth {
    Inf,
    Finite(NonZeroUsize),
}

impl FromStr for MaxDepth {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let t = s.trim();
        if t == "inf" {
            return Ok(MaxDepth::Inf);
        }
        match t.parse::<NonZeroUsize>() {
            Ok(v) => Ok(MaxDepth::Finite(v)),
            Err(e) => Err(format!("Value is neither \"inf\" nor a positive integer: {}", e)),
        }
    }
}

#[derive(Debug, Clone)]
enum Threads {
    Auto,
    Max,
    Num(NonZeroUsize),
}

impl FromStr for Threads {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let t = s.trim();
        if t == "auto" {
            return Ok(Threads::Auto);
        }
        if t == "max" {
            return Ok(Threads::Max);
        }
        match t.parse::<NonZeroUsize>() {
            Ok(v) => Ok(Threads::Num(v)),
            Err(e) => Err(format!("Value is neither \"auto\", \"max\", nor a number: {}", e)),
        }
    }
}

#[derive(Debug, Clone)]
struct MinRatio(f64);

impl FromStr for MinRatio {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let v: f64 = s.parse::<f64>().map_err(|e: std::num::ParseFloatError| e.to_string())?;
        if v.is_nan() {
            return Ok(MinRatio(v));
        }
        if v < 0.0 {
            return Err("less than 0".to_string());
        }
        if v >= 1.0 {
            return Err("greater than or equal to 1".to_string());
        }
        Ok(MinRatio(v))
    }
}

