// Internal tree (OsString names to handle non-UTF8 for chart, panic for JSON)
use std::collections::HashMap;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
use std::sync::Arc;

#[derive(Debug, Clone)]
struct FsNode {
    name: OsString, // basename for children of dirs, full arg string for roots/multiple
    full_path: PathBuf, // full path for hardlink counting (via starts_with); for "(total)" root, empty path
    size: u64, // non-deduped size in current quantity
    disp_size: u64, // deduped size for display (same as size when no -H)
    children: Vec<FsNode>,
    is_dir: bool,
}
#[derive(Debug, Clone)]
struct HLInfo { size: u64, nlink: u64, paths: Vec<PathBuf>, }

fn own_size(meta: &std::fs::Metadata, quantity: &str) -> u64 {
    match quantity {
        "apparent-size" => meta.len(),
        "block-size" => meta.blocks() * 512,
        "block-count" => meta.blocks(),
        _ => meta.blocks() * 512,
    }
}
fn report_error(silent: bool, msg: String) {
