#[derive(Debug, Clone)]
struct FsNode { name: OsString, full_path: std::path::PathBuf, size: u64, disp_size: u64, children: Vec<FsNode>, is_dir: bool, }
#[derive(Debug, Clone)]
struct HLInfo { size: u64, nlink: u64, paths: Vec<std::path::PathBuf>, }
fn own_size(meta: &std::fs::Metadata, q: &str) -> u64 {
    use std::os::unix::fs::MetadataExt;
    match q { "apparent-size" => meta.len(), "block-size" => meta.blocks()*512, "block-count" => meta.blocks(), _ => meta.blocks()*512, }
}
fn report_error(silent: bool, msg: String) {
    if silent { return; }
    use std::io::Write;
    let mut e = std::io::stderr();
    let _ = write!(e, "[error] {}\n\r\r", msg);
}
fn scan_path(path: &std::path::Path, name: OsString, quantity: &str, silent: bool, scanned: &std::sync::Arc<std::sync::atomic::AtomicU64>, total_c: &std::sync::Arc<std::sync::atomic::AtomicU64>, erred: &std::sync::Arc<std::sync::atomic::AtomicU64>, hlmap: &mut std::collections::HashMap<(u64,u64), HLInfo>) -> FsNode {
    use std::os::unix::fs::MetadataExt;
    let meta = match std::fs::symlink_metadata(path) {
        Ok(m) => m,
        Err(e) => { erred.fetch_add(1, std::sync::atomic::Ordering::Relaxed); report_error(silent, format!("symlink_metadata {:?}: {}", path, e)); return FsNode{name, full_path: path.to_path_buf(), size:0, disp_size:0, children:Vec::new(), is_dir:false}; }
    };
    let is_dir = meta.file_type().is_dir();
    scanned.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    if !is_dir {
        let sz = own_size(&meta, quantity);
        total_c.fetch_add(sz, std::sync::atomic::Ordering::Relaxed);
        let nlink = meta.nlink();
        if nlink > 1 {
            let key = (meta.dev(), meta.ino());
            let en = hlmap.entry(key).or_insert_with(|| HLInfo{size: sz, nlink, paths: Vec::new()});
            en.paths.push(path.to_path_buf());
        }
        return FsNode{name, full_path: path.to_path_buf(), size: sz, disp_size: sz, children:Vec::new(), is_dir:false};
    } else {
        let rd = match std::fs::read_dir(path) {
            Ok(r) => r,
            Err(e) => { erred.fetch_add(1, std::sync::atomic::Ordering::Relaxed); report_error(silent, format!("read_dir {:?}: {}", path, e)); return FsNode{name, full_path: path.to_path_buf(), size:0, disp_size:0, children:Vec::new(), is_dir:true}; }
        };
        let own = own_size(&meta, quantity);
        total_c.fetch_add(own, std::sync::atomic::Ordering::Relaxed);
        let mut children: Vec<FsNode> = Vec::new();
        for ent in rd {
            let entry = match ent {
                Ok(en) => en,
                Err(e) => { erred.fetch_add(1, std::sync::atomic::Ordering::Relaxed); report_error(silent, format!("read_dir {:?}: {}", path, e)); continue; }
            };
            let fname = entry.file_name();
            let fpath = entry.path();
            let child = scan_path(&fpath, fname, quantity, silent, scanned, total_c, erred, hlmap);
            children.push(child);
        }
        let sum: u64 = children.iter().map(|c| c.size).sum::<u64>().saturating_add(own);
        FsNode{name, full_path: path.to_path_buf(), size: sum, disp_size: sum, children, is_dir:true}
    }
}
fn merge_overlapping(files: Vec<OsString>, dedupe: bool) -> Vec<OsString> {
    if !dedupe || files.len() <= 1 { return files; }
    struct Cand { idx: usize, canon: std::path::PathBuf, }
    let mut cands: Vec<Cand> = Vec::new();
    let mut is_dir_flags: Vec<bool> = Vec::with_capacity(files.len());
    for (i,f) in files.iter().enumerate() {
        let p = std::path::Path::new(f);
        let is_dir = match std::fs::symlink_metadata(p) { Ok(m) => m.file_type().is_dir(), Err(_) => false, };
        is_dir_flags.push(is_dir);
        if is_dir { if let Ok(c) = std::fs::canonicalize(p) { cands.push(Cand{idx:i, canon:c}); } }
    }
    if cands.is_empty() { return files; }
    cands.sort_by_key(|c| c.canon.as_os_str().len());
    let mut kept_canon: Vec<std::path::PathBuf> = Vec::new();
    let mut keep_idx = std::collections::HashSet::new();
    for (i,_) in files.iter().enumerate() { if !is_dir_flags[i] { keep_idx.insert(i); } }
    for c in cands {
        let mut inside = false;
        for k in &kept_canon { if c.canon.starts_with(k) { inside=true; break; } }
        if !inside { kept_canon.push(c.canon.clone()); keep_idx.insert(c.idx); }
    }
    let mut out = Vec::new();
    for (i,f) in files.into_iter().enumerate() { if keep_idx.contains(&i) { out.push(f); } }
    out
}
fn sort_tree(node: &mut FsNode, no_sort: bool) {
    if !no_sort { node.children.sort_by(|a,b| b.size.cmp(&a.size)); }
    for c in node.children.iter_mut() { sort_tree(c, no_sort); }
}
fn filter_tree(node: &mut FsNode, total_non: u64, min_ratio: f64, max_depth: &MaxDepth, cur_depth: usize) {
    let max_d = match max_depth { MaxDepth::Inf => usize::MAX, MaxDepth::Finite(n) => n.get() };
    if cur_depth >= max_d { node.children.clear(); return; }
    let mut kept: Vec<FsNode> = Vec::new();
    for mut child in std::mem::take(&mut node.children) {
        let ratio = if total_non == 0 { f64::NAN } else { (child.size as f64)/(total_non as f64) };
        if !(ratio < min_ratio) {
            filter_tree(&mut child, total_non, min_ratio, max_depth, cur_depth+1);
            kept.push(child);
        }
    }
    node.children = kept;
}
fn apply_dedupe(node: &mut FsNode, hlmap: &std::collections::HashMap<(u64,u64), HLInfo>) {
    for c in node.children.iter_mut() { apply_dedupe(c, hlmap); }
    let mut dedupe: u64 = 0;
    let is_virtual = node.full_path.as_os_str().is_empty();
    for (_, info) in hlmap.iter() {
        let cnt = if is_virtual { info.paths.len() as u64 } else { info.paths.iter().filter(|p| p.starts_with(&node.full_path)).count() as u64 };
        if cnt > 1 { dedupe = dedupe.saturating_add((cnt-1).saturating_mul(info.size)); }
    }
    node.disp_size = node.size.saturating_sub(dedupe);
}
