fn format_bytes(size: u64, fmt: &str) -> String {
    if fmt == "plain" { return size.to_string(); }
    let (divisor, unit): (f32, &str) = if fmt == "metric" {
        if size < 1000 { return size.to_string(); }
        else if size < 1_000_000 { (1000.0f32, "K") }
