        else if size < 1048576 { (1024.0f32, "K") }
        else if size < 1073741824 { (1048576.0f32, "M") }
        else if size < 1099511627776 { (1073741824.0f32, "G") }
        else if size < 1125899906842624 { (1099511627776.0f32, "T") }
        else { (1125899906842624.0f32, "P") }
    };
    let v = (size as f32)/divisor;
    format!("{:.1}{}", v, unit)
}
fn is_plain(size: u64, fmt: &str, blocks: bool) -> bool {
    if blocks { return true; }
    if fmt=="plain" { return true; }
    if fmt=="metric" { return size<1000; }
    if fmt=="binary" { return size<1024; }
    true
}
