fn terminal_width() -> usize {
    fn ioctl_width(fd: i32) -> Option<usize> {
        #[repr(C)] struct Winsize { ws_row: u16, ws_col: u16, ws_xpixel: u16, ws_ypixel: u16, }
        let mut ws = Winsize{ws_row:0,ws_col:0,ws_xpixel:0,ws_ypixel:0};
        let ret = unsafe { libc::ioctl(fd, libc::TIOCGWINSZ, &mut ws) };
        if ret == 0 && ws.ws_col != 0 { Some(ws.ws_col as usize) } else { None }
    }
    if let Some(w) = ioctl_width(1) { return w; }
    if let Some(w) = ioctl_width(2) { return w; }
    150
}
fn rwidth(size: u64, total: u64, w: usize) -> usize {
    if total == 0 { return 0; }
    let v = (size as f64)/(total as f64)*(w as f64);
    v.round() as usize
}
fn pct(size: u64, total: u64) -> u32 {
    if total == 0 { return 0; }
    let v = (size as f64)/(total as f64)*100.0;
    v.round() as u32
}
