struct FRow<'a> { n: &'a FsNode, d: usize, ch: Vec<u64>, pf: Vec<bool>, pl: Vec<bool>, mf: bool, ml: bool, hk: bool, }
fn fcollect<'a>(n: &'a FsNode, d: usize, ch: &mut Vec<u64>, pf: &mut Vec<bool>, pl: &mut Vec<bool>, td: bool, out: &mut Vec<FRow<'a>>, mf: bool, ml: bool) {
    let mut full = ch.clone(); full.push(n.disp_size);
    let cf = pf.clone(); let cl = pl.clone();
    let k = n.children.len();
    let ord: Vec<usize> = if td { (0..k).collect() } else { (0..k).rev().collect() };
    if td {
        out.push(FRow{n, d, ch: full.clone(), pf: cf.clone(), pl: cl.clone(), mf, ml, hk: k>0});
        for (di,&ci) in ord.iter().enumerate() {
            let c=&n.children[ci]; let f=di==0; let l=di==k-1;
            if d>=1 { pf.push(mf); pl.push(ml); ch.push(n.disp_size); fcollect(c,d+1,ch,pf,pl,td,out,f,l); ch.pop(); pf.pop(); pl.pop(); }
            else { fcollect(c,d+1,ch,pf,pl,td,out,f,l); }
        }
    } else {
        for (di,&ci) in ord.iter().enumerate() {
            let c=&n.children[ci]; let f=di==0; let l=di==k-1;
            if d>=1 { pf.push(mf); pl.push(ml); ch.push(n.disp_size); fcollect(c,d+1,ch,pf,pl,td,out,f,l); ch.pop(); pf.pop(); pl.pop(); }
            else { fcollect(c,d+1,ch,pf,pl,td,out,f,l); }
        }
        out.push(FRow{n, d, ch: full, pf: cf, pl: cl, mf, ml, hk: k>0});
    }
}
