// Render filesystem chart. Returns lines to print.
fn render_chart_fs(root: &FsNode, total: u64, fmt: &str, blk: bool, td: bool, ar: bool, tw_opt: Option<usize>, cw_opt: Option<(usize,usize)>) -> Vec<String> {
    let mut ch0: Vec<u64> = Vec::new(); let mut pf0: Vec<bool> = Vec::new(); let mut pl0: Vec<bool> = Vec::new();
    let mut rows: Vec<FRow> = Vec::new();
    fcollect(root, 0, &mut ch0, &mut pf0, &mut pl0, td, &mut rows, true, true);
    if rows.is_empty() { return Vec::new(); }
    let (sw, pm) = size_w_fs(&rows, fmt, blk);
    // full trees (untruncated, unpadded)
    let mut fulls: Vec<String> = Vec::new();
    for r in &rows {
        fulls.push(full_tree_fs(r.d, &r.pf, &r.pl, r.mf, r.ml, r.hk, &r.node.name, td));
    }
    // determine tree_width and bar_width
    let (tree_w, bar_w): (usize, usize);
    let mut visible: Vec<bool> = vec![true; rows.len()];
    if let Some((tw, bw)) = cw_opt {
        let bw2 = bw.max(1);
        // tree_width = min(max_full_dw, tw+1)? Then hide where full_dw > tree_width? Actually hide where IB>tw? Simplify: hide where full_dw > tw+1? Truncate names to fit tree_width?
        // Compute full display widths
        let full_dw: Vec<usize> = fulls.iter().map(|s| dw(s)).collect();
