fn j_sort(n: &mut TreeNode, no: bool) { if !no { n.children.sort_by(|a,b| b.size.cmp(&a.size)); } for c in n.children.iter_mut() { j_sort(c, no); } }
fn j_filter(n: &mut TreeNode, tot: u64, mr: f64, md: &MaxDepth, d: usize) {
    let m = match md { MaxDepth::Inf => usize::MAX, MaxDepth::Finite(x) => x.get() };
    if d >= m { n.children.clear(); return; }
    let mut k: Vec<TreeNode> = Vec::new();
    for mut c in std::mem::take(&mut n.children) {
        let r = if tot==0 { f64::NAN } else { (c.size as f64)/(tot as f64) };
        if !(r < mr) { j_filter(&mut c, tot, mr, md, d+1); k.push(c); }
    }
    n.children = k;
}
